import sqlite3,re,collections
p='/home/USER/continual-arc-baselines/.workbench/stage1/H-hermes-luna6-high-fresh0/frozen/seen-reference/play/users/u016/system/state/hermes/state.db'; c=sqlite3.connect(p); sid='2939e437-227a-4a4a-b5ac-76437ffa0eb1'
for mid,text in c.execute('select id,content from messages where session_id=? and role="user" and active=1 order by id',(sid,)):
 for k in range(1,9):
  mm=re.search(rf'Demo pair {k} input \((\d+)x(\d+)\):\n(.*?)\nDemo pair {k} output \((\d+)x(\d+)\):\n(.*?)(?=\n\nSame instance\.|\Z)',text,re.S)
  if not mm: continue
  h,w=map(int,mm.group(1,2)); inp=[[int(x) for x in line.split()] for line in mm.group(3).splitlines() if line.strip()]; out=[[int(x) for x in line.split()] for line in mm.group(6).splitlines() if line.strip()]
  diffs=[(r,x,inp[r][x],out[r][x]) for r in range(h) for x in range(w) if inp[r][x]!=out[r][x]]
  bg=collections.Counter(v for row in inp for v in row).most_common(1)[0][0]
  ar=[r for r,row in enumerate(inp) if any(v!=bg for v in row)]
  # contiguous active row blocks
  blocks=[]
  for r in ar:
   if not blocks or r>blocks[-1][-1]+1: blocks.append([r])
   else: blocks[-1].append(r)
  print('\nDEMO',k,'bg',bg,'blocks',[(b[0],b[-1]) for b in blocks],'diffs',diffs)
  if len(blocks)>=2:
   A,B=blocks[0],blocks[-1]; n=min(len(A),len(B));
   scores=[]
   for dx in range(-5,6):
    mis=tot=0
    for i in range(n):
     ra,rb=A[i],B[i]
     for x in range(w):
