 if not t:continue
 for m in re.finditer(r'Demo pair (\d+) input \((\d+)x(\d+)\):\n(.*?)\nDemo pair \1 output \(\d+x\d+\):\n(.*?)(?=\n\n|\nSame instance|\Z)',t,re.S):
  n,h,w,ins,outs=m.groups(); parse=lambda s:[list(map(int,re.findall(r'\d+',x))) for x in s.strip().splitlines()]; demos[int(n)]=(parse(ins),parse(outs))
for n,(g,out) in sorted(demos.items()):
 bg=collections.Counter(x for row in g for x in row).most_common(1)[0][0]; active=[r for r,row in enumerate(g) if any(v!=bg for v in row)]; runs=[]
 for r in active:
