 ra,rb=runs[0],runs[-1]; marks=[(r,c) for r in range(len(g)) for c in range(len(g[r])) if out[r][c]==1 and g[r][c]!=1]
 print('D',n,'tops/bot',ra,rb,'marks',len(marks))
 for dx in [0,-2,-1,1,2]:
